// @ts-check
// French localization overlay for echo data — data/echoes.js.
// Keyed by the exact same names as ECHO_SETS / ECHO_DATA in echoes.js so it
// can be shallow-merged in at render time based on the active locale.
//
// Terminology sourced from the official French site (official — takes
// precedence) and the French reference (community-maintained, secondary).
// Element names (Glacio, Fusion, Electro, Aero, Spectro, Havoc) are kept
// untranslated per the official French Play Store listing and site, which
// use them as-is even in French copy (e.g. "Qingxiao (Aero, Sabre)").
// "Intro"/"Outro" skill triggers: the French reference confirms "compétence d'intro"
// / "compétence d'outro" as the translated form; kept short as "Intro"/"Outro"
// in terse mechanical strings (matches how the rest of this app's fr locale
// keeps short mechanical tokens untranslated, e.g. teams.json).
//
// Elemental RES-shred proc names (Spectro Frazzle, Havoc Bane, Fusion Burst, Electro Flare,
// Glacio Chafe, Aero Erosion) are now confirmed against the game's actual French client
// (user-provided, not from either source above): Lumière Spectro, Ravage Havoc, Explosion
// Fusion, Électromagnétisme, Givre Glaçant, Érosion Aéronautique — same terms used in
// characters.fr.js's own PHRASE_FR/MULT_DESC_FR tables and RotationTimeline.jsx's
// STAT_LABELS_FR.

// RANK_FR — echo/boss rank badge (ECHO_DATA[name].rank, MonsterCard.jsx's rank prop and
// EnemyEchoSelectorModal's rank filter). Same terms already established in ECHO_DATA_FR's own
// prose below (Seigneur/Calamité/Élite/Commun for Overlord/Calamity/Elite/Common).
/** @type {Record<string, string>} */
export const RANK_FR = { Calamity: 'Calamité', Overlord: 'Seigneur', Elite: 'Élite', Common: 'Commun' };

